import React, { useEffect, useRef } from 'react';
import { useReducedMotion } from 'framer-motion';
import Lenis from 'lenis';
import { ThemeProvider, useTheme } from './context/ThemeContext';
import Navbar from './components/Navbar';
import HeroSection from './components/sections/HeroSection';
import AboutSection from './components/sections/AboutSection';
import ProjectsSection from './components/sections/ProjectsSection';
import SkillsSection from './components/sections/SkillsSection';
import ExperienceSection from './components/sections/ExperienceSection';
import ContactSection from './components/sections/ContactSection';
import Footer from './components/Footer';
import ErrorBoundary from './components/ErrorBoundary';
import { cn } from './lib/cn';
import './App.css';

const AppContent = () => {
  const { isDark } = useTheme();
  const shouldReduceMotion = useReducedMotion();
  const lenisRef = useRef(null);

  useEffect(() => {
    if (shouldReduceMotion) {
      document.documentElement.style.scrollBehavior = 'auto';
      return;
    }
    const lenis = new Lenis({ duration: 1.2, smoothWheel: true });
    lenisRef.current = lenis;
    function raf(time) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }
    requestAnimationFrame(raf);
    return () => {
      lenis.destroy();
      lenisRef.current = null;
    };
  }, [shouldReduceMotion]);

  useEffect(() => {
    if (shouldReduceMotion) return;
    document.documentElement.style.scrollBehavior = 'smooth';
    return () => { document.documentElement.style.scrollBehavior = ''; };
  }, [shouldReduceMotion]);

  return (
    <div className={cn('min-h-screen transition-colors duration-300', isDark ? 'bg-dark-bg text-dark-text' : 'bg-light-bg text-light-text')}>
      {/* Skip link - visible on focus for keyboard/screen reader */}
      <a
        href="#main"
        className="absolute left-4 top-4 -translate-y-[150%] z-[100] px-4 py-2 bg-primary text-white rounded-lg font-mono text-sm focus:translate-y-0 focus:outline-none focus:ring-2 focus:ring-white focus:ring-offset-2 focus:ring-offset-dark-bg"
      >
        Skip to main content
      </a>
      {/* Noise Overlay */}
      <div className="noise-overlay" aria-hidden="true" />
      
      {/* Navigation */}
      <Navbar />
      
      {/* Main Content */}
      <main id="main">
        <HeroSection />
        <AboutSection />
        <ProjectsSection />
        <SkillsSection />
        <ExperienceSection />
        <ContactSection />
      </main>
      
      {/* Footer */}
      <Footer />
    </div>
  );
};

function App() {
  return (
    <ThemeProvider>
      <ErrorBoundary>
        <AppContent />
      </ErrorBoundary>
    </ThemeProvider>
  );
}

export default App;
